int invertirAux(int n, int invertido) {
  if (n == 0) {
    return invertido;
  }
  return invertirAux(n / 10, invertido * 10 + n % 10);
}

int invertir(int n) {
  return invertirAux(n, 0);
}

int binarioAux(int n, int lugar) {
  if (n == 0) {
    return 0;
  }
  return n % 2 * lugar + binarioAux(n / 2, lugar * 10);
}

int binario(int n) {
  return binarioAux(n, 1);
}

int posicionDesde(int v[], int n, int valor, int i) {
  if (i == n) {
    return -1;
  }
  if (v[i] == valor) {
    return i;
  }
  return posicionDesde(v, n, valor, i + 1);
}

int posicion(int v[], int n, int valor) {
  return posicionDesde(v, n, valor, 0);
}

TBool capicuaAux(int n, int alReves, int original) {
  if (n == 0) {
    if (alReves == original) {
      return VERDADERO;
    }
    return FALSO;
  }
  return capicuaAux(n / 10, alReves * 10 + n % 10, original);
}

TBool esCapicua(int n) {
  return capicuaAux(n, 0, n);
}
